#!/usr/bin/env bash
#
# Regenerates the Go, TypeScript and Rust code of every message contract in
# shared/contracts/<domain>/openapi.yaml. With --check it changes nothing and
# exits non-zero if any generated file differs from what is committed.
#
#   gen-schemas.sh           rewrite the generated files
#   gen-schemas.sh --check   generate into a temporary directory and diff
#
# Pinned tools: ogen (a `tool` line in scripts/contracts/go.mod),
# openapi-typescript, ajv and @redocly/openapi-core (scripts/contracts/
# package.json and bun.lock) and cargo-typify (TYPIFY_VERSION below, installed
# under scripts/contracts/.tools). jq and rustfmt come from the toolchain.

set -euo pipefail

readonly TYPIFY_VERSION="0.10.1"

cd "$(git rev-parse --show-toplevel)"

check=false
case "${1:-}" in
  "") ;;
  --check) check=true ;;
  *)
    echo "usage: $0 [--check]" >&2
    exit 2
    ;;
esac

# One line per contract: its domain (the directory under shared/contracts),
# then where each language's generated code lives. Each lives in the consuming
# package, next to hand-written files, so only the generated files are replaced:
# `*_gen.go` in the Go directory, `<domain>.gen.ts` and `<domain>.validate.gen.ts`
# in the TypeScript directory, and the Rust file itself.
readonly DOMAINS=(
  "scene shared/common/golang/messages/scene shared/common/typescript/cloudevents/Scene shared/common/rust/cloudevents/src/scene_gen.rs"
  "barkloader shared/common/golang/messages/barkloader shared/common/typescript/cloudevents/Barkloader shared/common/rust/cloudevents/src/barkloader_gen.rs"
  "stream shared/common/golang/messages/stream shared/common/typescript/cloudevents/Twitch shared/common/rust/cloudevents/src/stream_gen.rs"
)

tools=scripts/contracts
if ! cargo install --list --root "$tools/.tools" 2>/dev/null | grep -q "^cargo-typify v$TYPIFY_VERSION"; then
  rm -rf "$tools/.tools"
  cargo install --locked cargo-typify --version "$TYPIFY_VERSION" --root "$tools/.tools" >&2
fi
export PATH="$PWD/$tools/node_modules/.bin:$PWD/$tools/.tools/bin:$PATH"

out="$(mktemp -d)"
trap 'rm -rf "$out"' EXIT

for entry in "${DOMAINS[@]}"; do
  read -r domain go_dir ts_dir rust_file <<<"$entry"
  source="shared/contracts/$domain/openapi.yaml"
  header="Generated by scripts/gen-schemas.sh from $source. Do not edit."
  doc="$out/$domain.json"

  bun "$tools/bundle.ts" "$source" "$doc"

  # The operation path is the subject, and the generated `type` constant must say the same.
  jq -e '. as $d | .paths | to_entries | all(.[]; (.value.post.requestBody.content["application/json"].schema["$ref"] | split("/")[-1]) as $n | "/" + $d.components.schemas[$n].properties.type.enum[0] == .key)' "$doc" >/dev/null ||
    { echo "gen-schemas: $source: an operation path is not the \`type\` its request fixes" >&2; exit 1; }

  # Go: types, enums, tagged unions and validators; no client or server.
  mkdir -p "$out/$go_dir"
  (cd "$tools" && go tool ogen -config ogen.yaml -package "$domain" -target "$out/$go_dir" -clean "$doc") 2>"$out/ogen.log" || { cat "$out/ogen.log" >&2; exit 1; }
  # ogen skips what it cannot generate, with only a log line; a skipped operation or schema must fail the run.
  if grep -q "Skipping" "$out/ogen.log"; then
    cat "$out/ogen.log" >&2
    echo "gen-schemas: ogen skipped part of $source" >&2
    exit 1
  fi
  for schema in $(jq -r '.components.schemas | keys[]' "$doc"); do
    grep -q "^type $schema " "$out/$go_dir"/oas_schemas_gen.go || { echo "gen-schemas: ogen generated no Go type for $schema of $source" >&2; exit 1; }
  done
  sed -i "s|^// Code generated by ogen, DO NOT EDIT\.|// Code generated by scripts/gen-schemas.sh (ogen) from $source. DO NOT EDIT.|" "$out/$go_dir"/*.go

  # TypeScript: types with run-time enums, and precompiled Ajv validators.
  mkdir -p "$out/$ts_dir"
  openapi-typescript "$doc" --root-types --enum --default-non-nullable false -o "$out/$ts_dir/$domain.gen.ts" >/dev/null
  sed -i "1i // $header" "$out/$ts_dir/$domain.gen.ts"
  bun "$tools/ajv-standalone.ts" "$doc" "$domain.gen" "$out/$ts_dir/$domain.validate.gen.ts"
  sed -i "1i // $header\n// @ts-nocheck" "$out/$ts_dir/$domain.validate.gen.ts"

  # Rust: typify reads JSON Schema definitions, so the document's components are lifted out first. The document
  # is embedded for the run-time validator.
  mkdir -p "$out/$(dirname "$rust_file")"
  jq -f "$tools/typify-prep.jq" "$doc" | sed 's|#/components/schemas/|#/definitions/|g' >"$out/$domain.defs.json"
  cargo typify "$out/$domain.defs.json" -B --output "$out/$rust_file" >/dev/null 2>&1
  {
    echo "// $header"
    cat "$out/$rust_file"
    printf '\n/// The contract document the run-time validator reads.\npub const DOCUMENT: &str = r####"%s"####;\n' "$(jq -c . "$doc")"
  } >"$out/$rust_file.tmp"
  mv "$out/$rust_file.tmp" "$out/$rust_file"
  rustfmt --edition 2021 "$out/$rust_file"
done

# The first lines of a difference; the validators are one very long line each.
show_diff() {
  diff -uN "$@" | cut -c1-160 | head -n 30
  return "${PIPESTATUS[0]}"
}

stale=0
for entry in "${DOMAINS[@]}"; do
  read -r domain go_dir ts_dir rust_file <<<"$entry"
  single_files=("$ts_dir/$domain.gen.ts" "$ts_dir/$domain.validate.gen.ts" "$rust_file")
  if $check; then
    # -N reports a file present on one side only as a difference.
    show_diff -r --exclude='*_test.go' "$go_dir" "$out/$go_dir" >&2 || stale=1
    for f in "${single_files[@]}"; do
      show_diff "$f" "$out/$f" >&2 || stale=1
    done
  else
    mkdir -p "$go_dir"
    rm -f "$go_dir"/*_gen.go
    cp "$out/$go_dir"/*.go "$go_dir/"
    for f in "${single_files[@]}"; do
      mkdir -p "$(dirname "$f")"
      cp "$out/$f" "$f"
    done
  fi
done
if [ "$stale" -ne 0 ]; then
  echo "gen-schemas: generated files are out of date; run scripts/gen-schemas.sh and commit the result" >&2
  exit 1
fi
